window.MURB_EXCEL_TEMPLATE_B64='';
/* MURB: exportação oficial, sem redesenhar o modelo do Excel. */
(function(){
'use strict';
const NS='http://schemas.openxmlformats.org/spreadsheetml/2006/main';
const names=['AD1','IG2','C10','C12','C13','C15','CEMITERIO URBANO','CEMITERO S.J BATISTA','PODA ARTISTICA','VD6','VD8','LAGOA DA COMPENSA','APRENDIZ 1 TURNO','APRENDIZ 2 TURNO'];
const offsets=[0,4,8,12,16,20,24,28,32,36,40,44,48,53];
const normalized=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Za-z0-9]/g,'').toUpperCase();
const col=i=>{let s='';for(i++;i;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s;};
const xmlParse=s=>{const doc=new DOMParser().parseFromString(s,'application/xml');if(doc.getElementsByTagName('parsererror').length)throw Error('XML da planilha inválido');return doc;};
function cell(doc,ref){return Array.from(doc.getElementsByTagNameNS(NS,'c')).find(c=>c.getAttribute('r')===ref);}
function ensureCell(doc,ref){let c=cell(doc,ref);if(c)return c;
 const match=ref.match(/^([A-Z]+)(\d+)$/),letter=match[1],rowNumber=Number(match[2]);
 const sheetData=doc.getElementsByTagNameNS(NS,'sheetData')[0];
 let row=Array.from(sheetData.getElementsByTagNameNS(NS,'row')).find(r=>Number(r.getAttribute('r'))===rowNumber);
 if(!row){row=doc.createElementNS(NS,'row');row.setAttribute('r',String(rowNumber));const next=Array.from(sheetData.getElementsByTagNameNS(NS,'row')).find(r=>Number(r.getAttribute('r'))>rowNumber);sheetData.insertBefore(row,next||null);}
 const original=cell(doc,letter+'9');c=original?original.cloneNode(true):doc.createElementNS(NS,'c');c.setAttribute('r',ref);
 const number=str=>Array.from(str).reduce((n,ch)=>n*26+ch.charCodeAt(0)-64,0);
 const next=Array.from(row.getElementsByTagNameNS(NS,'c')).find(x=>number(x.getAttribute('r').replace(/\d+$/,''))>number(letter));row.insertBefore(c,next||null);
 const dimension=doc.getElementsByTagNameNS(NS,'dimension')[0];if(dimension){const old=dimension.getAttribute('ref'),m=old.match(/^(.*?:[A-Z]+)(\d+)$/);if(m&&Number(m[2])<rowNumber)dimension.setAttribute('ref',m[1]+rowNumber);}
 return c;
}
function setCell(doc,ref,value){const c=ensureCell(doc,ref);while(c.firstChild)c.removeChild(c.firstChild);c.setAttribute('t','inlineStr');const is=doc.createElementNS(NS,'is'),t=doc.createElementNS(NS,'t');t.setAttribute('xml:space','preserve');t.textContent=String(value??'');is.appendChild(t);c.appendChild(is);}
function readGroups(){
 if(typeof data==='undefined'||!Array.isArray(data.teams)||!Array.isArray(data.employees))throw Error('Cadastro de funcionários indisponível');
 const people=data.employees.filter(e=>normalized(e.status).toLowerCase()==='ativo');
 return data.teams.map(t=>({name:String(t.name||'').trim(),lead:String(t.lead||t.fiscal||t.supervisor||'Não informado'),people:people.filter(e=>String(e.teamId)===String(t.id)).sort((a,b)=>String(a.name||'').localeCompare(String(b.name||''),'pt-BR')).map(e=>({name:String(e.name||''),role:String(e.role||'')}))})).filter(g=>g.name);
}
function fill(doc,group,start){
 const a=col(start),b=col(start+1),c=col(start+2);
 const sheetData=doc.getElementsByTagNameNS(NS,'sheetData')[0];
 const existing=Array.from(sheetData.getElementsByTagNameNS(NS,'row'));
 const max=Math.max(...existing.map(r=>Number(r.getAttribute('r'))));
 const last=Math.max(max,8+group.people.length);
 const date=new Date().toLocaleString('pt-BR');
 setCell(doc,a+'1','MURB SERVIÇOS — ADSON ROCHA');
 setCell(doc,a+'2','Emitido em '+date);
 setCell(doc,a+'4','Equipe: '+group.name);
 setCell(doc,a+'5','Fiscal: '+group.lead);
 setCell(doc,a+'6','Total de funcionários: '+group.people.length);
 for(let row=9;row<=last;row++){
  const p=group.people[row-9];
  // A célula existente conserva a propriedade s (estilo), e as demais estruturas não são tocadas.
  for(const [ref,value] of [[a+row,p?row-8:''],[b+row,p?p.name:''],[c+row,p?p.role:'']]){
   if(cell(doc,ref)||p)setCell(doc,ref,value);
  }
 }
}
function download(blob){
 const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MURB_EQUIPES_'+new Date().toISOString().slice(0,10)+'.xlsx';a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
}
let running=false;
window.murbExportEmployeesByTeamExcelOfficial=async function(){
 if(running)return;
 running=true;
 try{
  if(typeof JSZip==='undefined')throw Error('Biblioteca de arquivos Excel não carregada');
  const groups=readGroups(),lookup=new Map(groups.map(g=>[normalized(g.name),g]));
  const extra=groups.filter(g=>!names.some(n=>normalized(n)===normalized(g.name)));
  const ordered=names.map(n=>lookup.get(normalized(n))||{name:n,lead:'Não informado',people:[]});
  const binary=atob(window.MURB_EXCEL_TEMPLATE_B64);const bytes=new Uint8Array(binary.length);
  for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
  const zip=await JSZip.loadAsync(bytes);
  const generalPath='xl/worksheets/sheet1.xml';const general=xmlParse(await zip.file(generalPath).async('string'));
  for(let i=0;i<ordered.length;i++)fill(general,ordered[i],offsets[i]);
  zip.file(generalPath,new XMLSerializer().serializeToString(general));
  for(let i=0;i<ordered.length;i++){
   const path='xl/worksheets/sheet'+(i+2)+'.xml';const part=zip.file(path);
   if(!part)throw Error('Aba '+names[i]+' não encontrada no modelo');
   const doc=xmlParse(await part.async('string'));fill(doc,ordered[i],0);zip.file(path,new XMLSerializer().serializeToString(doc));
  }
  if(extra.length){
    // Acrescenta novas abas no próprio XLSX e registra-as nas relações do Office.
    const workbook=xmlParse(await zip.file('xl/workbook.xml').async('string'));
    const relationships=xmlParse(await zip.file('xl/_rels/workbook.xml.rels').async('string'));
    const types=xmlParse(await zip.file('[Content_Types].xml').async('string'));
    const sheets=workbook.getElementsByTagNameNS(NS,'sheets')[0];
    const relNS='http://schemas.openxmlformats.org/package/2006/relationships';
    const typeNS='http://schemas.openxmlformats.org/package/2006/content-types';
    const officeRel='http://schemas.openxmlformats.org/officeDocument/2006/relationships';
    const usedNames=new Set(Array.from(sheets.children).map(s=>normalized(s.getAttribute('name'))));
    let sheetId=Math.max(...Array.from(sheets.children).map(s=>Number(s.getAttribute('sheetId'))));
    let rid=Math.max(...Array.from(relationships.documentElement.children).map(r=>Number((r.getAttribute('Id')||'').replace('rId',''))||0));
    const sample=xmlParse(await zip.file('xl/worksheets/sheet15.xml').async('string'));
    for(let i=0;i<extra.length;i++){
      const g=extra[i];
      const doc=sample.cloneNode(true);
      fill(doc,g,0);
      const path='xl/worksheets/sheet'+(16+i)+'.xml';
      zip.file(path,new XMLSerializer().serializeToString(doc));
      const sh=workbook.createElementNS(NS,'sheet');
      let name=g.name.replace(/[\\/:?*\[\]]/g,' ').trim().slice(0,31)||'EQUIPE NOVA';
      let base=name,n=2;
      while(usedNames.has(normalized(name))){name=base.slice(0,27)+' '+n++;}
      usedNames.add(normalized(name));
      sh.setAttribute('name',name);sh.setAttribute('sheetId',String(++sheetId));
      sh.setAttributeNS(officeRel,'r:id','rId'+(++rid));sheets.appendChild(sh);
      const rel=relationships.createElementNS(relNS,'Relationship');
      rel.setAttribute('Id','rId'+rid);rel.setAttribute('Type',officeRel+'/worksheet');
      rel.setAttribute('Target','worksheets/sheet'+(16+i)+'.xml');relationships.documentElement.appendChild(rel);
      const ov=types.createElementNS(typeNS,'Override');
      ov.setAttribute('PartName','/'+path);
      ov.setAttribute('ContentType','application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml');types.documentElement.appendChild(ov);
      // Reproduz na aba EQUIPES o bloco visual da última equipe do modelo.
      const shift=58+i*5-53;
      const rows=Array.from(general.getElementsByTagNameNS(NS,'row'));
      for(const row of rows){
        const originals=Array.from(row.getElementsByTagNameNS(NS,'c')).filter(c=>{
          const m=(c.getAttribute('r')||'').match(/^([A-Z]+)\d+$/);
          if(!m)return false;
          let v=0;for(const ch of m[1])v=v*26+ch.charCodeAt(0)-64;
          return v>=54&&v<=57;
        });
        for(const original of originals){
          const clone=original.cloneNode(true);
          const ref=original.getAttribute('r');
          const m=ref.match(/^([A-Z]+)(\d+)$/);
          let v=0;for(const ch of m[1])v=v*26+ch.charCodeAt(0)-64;
          clone.setAttribute('r',col(v-1+shift)+m[2]);
          row.appendChild(clone);
        }
      }
      fill(general,g,58+i*5);
    }
    // Mesclagens do bloco final, replicadas para as novas equipes.
    const merges=general.getElementsByTagNameNS(NS,'mergeCells')[0];
    if(merges){
      const originals=Array.from(merges.children).filter(m=>{
        const match=(m.getAttribute('ref')||'').match(/^([A-Z]+)\d+:/);
        if(!match)return false;let v=0;for(const ch of match[1])v=v*26+ch.charCodeAt(0)-64;
        return v>=54&&v<=57;
      });
      const shiftRef=(ref,offset)=>ref.replace(/([A-Z]+)(\d+)/g,(_,letters,row)=>{
        let v=0;for(const ch of letters)v=v*26+ch.charCodeAt(0)-64;
        return col(v-1+offset)+row;
      });
      for(let i=0;i<extra.length;i++)for(const m of originals){const copy=m.cloneNode(true);copy.setAttribute('ref',shiftRef(m.getAttribute('ref'),5*(i+1)));merges.appendChild(copy);}
      merges.setAttribute('count',String(merges.children.length));
    }
    zip.file('xl/workbook.xml',new XMLSerializer().serializeToString(workbook));
    zip.file('xl/_rels/workbook.xml.rels',new XMLSerializer().serializeToString(relationships));
    zip.file('[Content_Types].xml',new XMLSerializer().serializeToString(types));
    zip.file(generalPath,new XMLSerializer().serializeToString(general));
  }
  const result=await zip.generateAsync({type:'blob',compression:'DEFLATE',mimeType:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});
  if(result.size<10000)throw Error('Arquivo Excel gerado incompleto');
  download(result);
  if(typeof toast==='function')toast('Planilha oficial Excel gerada: '+(15+extra.length)+' abas.');
 }catch(err){console.error('MURB exportação Excel oficial:',err);alert('Falha ao baixar Excel oficial: '+err.message);}
 finally{running=false;}
};
})();
